def save_msg_json(filename, body, subject, msg_id, created_at):
    """Save a single SEEK email as a tool-results-style JSON file."""
    out = {
        "data": {
            "data": {
                "message_id": msg_id,
                "subject": subject,
                "body": body,
                "body_format": 2,
                "is_read": True,
                "has_attachments": False,
                "attachment_count": 0,
                "created_at": created_at,
            }
        }
    }
    out_path = CACHE / filename
    with open(out_path, 'w', encoding='utf-8') as f:
        json.dump(out, f, ensure_ascii=False, indent=2)
    print(f"Saved: {out_path} ({len(body)} bytes body)")
    return out_path


